CP4 = (192, 0, 2, 1)
UP4 = (192, 0, 2, 2)
CP6 = bytes.fromhex('20010db8000000000000000000000001')
UP6 = bytes.fromhex('20010db8000000000000000000000002')

# ---------------------------------------------------------------- pcapng
class Out:
    def __init__(self):
        self.frames = []      # (ifid, data, ts_us)
        self.t = 1700000000 * 1000000
        self.marks = []

    def mark(self, name):
        self.marks.append((len(self.frames) + 1, name))

    def add(self, data, ifid=0, dt=1000):
        self.t += dt
        self.frames.append((ifid, data, self.t))

    def write(self, fn):
        def blk(t, body):
            body += b'\0' * (-len(body) % 4)
            return struct.pack('<II', t, len(body) + 12) + body + struct.pack('<I', len(body) + 12)
        out = blk(0x0a0d0d0a, struct.pack('<IHHq', 0x1a2b3c4d, 1, 0, -1))
        out += blk(1, struct.pack('<HHI', 1, 0, 262144))
        out += blk(1, struct.pack('<HHI', 252, 0, 262144))
        for ifid, d, ts in self.frames:
            out += blk(6, struct.pack('<IIIII', ifid, ts >> 32, ts & 0xffffffff, len(d), len(d)) + d)
        with open(fn, 'wb') as f:
            f.write(out)


def csum(b):
    if len(b) % 2:
        b += b'\0'
    s = 0
    for i in range(0, len(b), 2):
        s += (b[i] << 8) | b[i + 1]
    while s >> 16:
        s = (s & 0xffff) + (s >> 16)
    return (~s) & 0xffff


def udp4(payload, src=CP4, dst=UP4, sport=PFCP_PORT, dport=PFCP_PORT):
    u = struct.pack('!HHHH', sport, dport, 8 + len(payload), 0) + payload
    ip = struct.pack('!BBHHHBBH4s4s', 0x45, 0, 20 + len(u), 1, 0, 64, 17, 0, bytes(src), bytes(dst))
    ip = ip[:10] + struct.pack('!H', csum(ip)) + ip[12:]
    return b'\x02\0\0\0\0\x02\x02\0\0\0\0\x01\x08\x00' + ip + u


def udp6(payload, src=CP6, dst=UP6, sport=PFCP_PORT, dport=PFCP_PORT):
    u = struct.pack('!HHHH', sport, dport, 8 + len(payload), 0) + payload
    ph = src + dst + struct.pack('!IBBBB', len(u), 0, 0, 0, 17)
    c = csum(ph + u)
    u = u[:6] + struct.pack('!H', c or 0xffff) + u[8:]
    ip = struct.pack('!IHBB16s16s', 0x60000000, len(u), 17, 64, src, dst)
    return b'\x02\0\0\0\0\x02\x02\0\0\0\0\x01\x86\xdd' + ip + u


# ---------------------------------------------------------------- PFCP
def ie(t, v=b''):
    return struct.pack('!HH', t, len(v)) + v


def vie(ent, t, v=b''):
    return struct.pack('!HHH', t, len(v) + 2, ent) + v


def msg(mtype, ies=b'', seid=None, seq=1, mp=None, fo=False, ver=1, spare=0):
    flags = (ver << 5) | (spare << 3) | (4 if fo else 0) | (2 if mp is not None else 0) | (1 if seid is not None else 0)
    body = b''
    if seid is not None:
        body += struct.pack('!Q', seid)
    body += bytes([(seq >> 16) & 255, (seq >> 8) & 255, seq & 255, (mp << 4) if mp is not None else 0])
    body += ies
    return struct.pack('!BBH', flags, mtype, len(body)) + body


def fl(f, L, fill=0x11):
    return bytes([f]) + bytes([fill]) * (L - 1)

def node_id4(a=CP4):
    return ie(60, b'\x00' + bytes(a))


def node_id6(a=CP6):
    return ie(60, b'\x01' + a)


def node_fqdn(name='cp.example.net'):
    enc = b''.join(bytes([len(x)]) + x.encode() for x in name.split('.'))
    return ie(60, b'\x02' + enc)


def recovery_ts(t=0xe6a3b100):
    return ie(96, struct.pack('!I', t))


def cause(c=1):
    return ie(19, bytes([c]))


def fseid4(seid, a=CP4):
    return ie(57, b'\x02' + struct.pack('!Q', seid) + bytes(a))


def fseid6(seid, a=CP6):
    return ie(57, b'\x01' + struct.pack('!Q', seid) + a)


def fseid46(seid, a4=CP4, a6=CP6):
    return ie(57, b'\x03' + struct.pack('!Q', seid) + bytes(a4) + a6)


def pdr_id(i):
    return ie(56, struct.pack('!H', i))


def far_id(i):
    return ie(108, struct.pack('!I', i))


def urr_id(i):
    return ie(81, struct.pack('!I', i))


def qer_id(i):
    return ie(109, struct.pack('!I', i))


def bar_id(i):
    return ie(88, bytes([i]))


def precedence(p):
    return ie(29, struct.pack('!I', p))


def src_if(i):
    return ie(20, bytes([i]))


def dst_if(i):
    return ie(42, bytes([i]))


def netinst(name='internet'):
    return ie(22, bytes([len(name)]) + name.encode())


def fteid4(teid, a=UP4):
    return ie(21, b'\x01' + struct.pack('!I', teid) + bytes(a))


def fteid_ch():
    return ie(21, b'\x04')


def ue_ip4(a=(10, 45, 0, 7)):
    return ie(93, b'\x02' + bytes(a))


def apply_action(f=2):
    return ie(44, bytes([f]))


def user_id_imsi(imsi='001010000000003'):
    d = imsi + ('f' if len(imsi) % 2 else '')
    tb = bytes(int(d[i + 1], 16) << 4 | int(d[i], 16) for i in range(0, len(d), 2))
    return ie(141, b'\x01' + bytes([len(tb)]) + tb)


def ohc4(teid, a):
    return ie(84, struct.pack('!HI', 0x0100, teid) + bytes(a))


def pdi(*c):
    return ie(2, b''.join(c))


def create_pdr(i, *c):
    return ie(1, pdr_id(i) + b''.join(c))


def create_far(i, *c):
    return ie(3, far_id(i) + b''.join(c))


def fwd_params(*c):
    return ie(4, b''.join(c))


def create_urr(i, *c):
    return ie(6, urr_id(i) + b''.join(c))


def create_qer(i, *c):
    return ie(7, qer_id(i) + b''.join(c))


def created_pdr(i, *c):
    return ie(8, pdr_id(i) + b''.join(c))


def sweep_payload(f, n):
    return fl(f, n)


def build(o, vflag):
    seq = [100]

    def nxt():
        seq[0] += 1
        return seq[0]

    def send(m, v6=False, **kw):
        o.add((udp6 if v6 else udp4)(m, **kw))

    def pair(req, resp, rin=b'', pin=b'', seid_req=None, seid_resp=None, v6=False):
        s = nxt()
        o.add((udp6 if v6 else udp4)(msg(req, rin, seid=seid_req, seq=s)))
        if v6:
            o.add(udp6(msg(resp, pin, seid=seid_resp, seq=s), src=UP6, dst=CP6))
        else:
            o.add(udp4(msg(resp, pin, seid=seid_resp, seq=s), src=UP4, dst=CP4))

    # ---- 1. node messages
    o.mark('node related messages')
    pair(1, 2, recovery_ts(), recovery_ts(0xe6a3b200))
    pair(1, 2, recovery_ts(), recovery_ts(), v6=True)
    pair(3, 4, ie(58, ie(24, b'\x00\x05' + b'video') + ie(59, ie(61, b'\x01\x00\x00\x0a' + b'permit out'))), cause(1) + node_id4(UP4))
    pair(5, 6, node_id4() + recovery_ts() + ie(89, b'\x07') + ie(116, b'\x01\x00\x00\x00\x00'),
         cause(1) + node_id4(UP4) + recovery_ts() + ie(43, b'\xff\xff'))
    pair(5, 6, node_id6() + recovery_ts(), cause(65) + node_id6(UP6) + recovery_ts(), v6=True)
    pair(5, 6, node_fqdn() + recovery_ts(), cause(1) + node_fqdn('up.example.net'))
    pair(7, 8, node_id4(), cause(1) + node_id4(UP4))
    pair(9, 10, node_id4(), cause(1) + node_id4(UP4))
    pair(12, 13, node_id4() + ie(101, b'\x01'), cause(1))
    pair(14, 15, node_id4() + ie(65, fl(1, 7)), cause(1) + node_id4(UP4))
    pair(16, 17, node_id4(), cause(1) + node_id4(UP4))
    o.add(udp4(msg(11, b'', seq=7), src=UP4, dst=CP4))

    # ---- 2. session messages
    o.mark('session messages')
    cp_seid, up_seid = 0xc1, 0xa1
    s = nxt()
    o.add(udp4(msg(50, node_id4() + fseid4(cp_seid) + user_id_imsi() +
                   create_pdr(1, precedence(100), pdi(src_if(0), fteid_ch(), netinst(), ue_ip4()), ie(95, b'\x00'), far_id(1), urr_id(1), qer_id(1)) +
                   create_far(1, apply_action(2), fwd_params(dst_if(1), netinst('internet'), ohc4(0x4101, UP4))) +
                   create_urr(1, ie(62, b'\x01\x00'), ie(37, b'\x02\x00\x00\x00\x00\x10\x00')) +
                   create_qer(1, ie(25, b'\x03'), ie(26, b'\x00\x00\x00\x03\xe8\x00\x00\x00\x03\xe8')) +
                   ie(49, b'\x01'), seid=0, seq=s)))
    o.add(udp4(msg(51, cause(1) + node_id4(UP4) + fseid4(up_seid, UP4) +
                   created_pdr(1, fteid4(0x3101)), seid=cp_seid, seq=s), src=UP4, dst=CP4))
    s = nxt()
    o.add(udp4(msg(52, ie(10, far_id(1) + apply_action(2) + ie(11, dst_if(1) + ohc4(0x4101, UP4))) +
                   ie(13, urr_id(1)) + ie(15, pdr_id(1)), seid=up_seid, seq=s)))
    o.add(udp4(msg(53, cause(1), seid=cp_seid, seq=s), src=UP4, dst=CP4))
    s = nxt()
    o.add(udp4(msg(56, ie(39, b'\x02') + ie(80, urr_id(1) + ie(104, struct.pack('!I', 1))), seid=cp_seid, seq=s), src=UP4, dst=CP4))
    o.add(udp4(msg(57, cause(1), seid=up_seid, seq=s)))
    s = nxt()
    o.add(udp4(msg(54, b'', seid=up_seid, seq=s)))
    o.add(udp4(msg(55, cause(1), seid=cp_seid, seq=s), src=UP4, dst=CP4))

    # ---- 3. header variants
    o.mark('header variants')
    o.add(udp4(msg(1, recovery_ts(), mp=5, seq=nxt())))
    o.add(udp4(msg(52, pdr_id(1), seid=0x77, mp=15, seq=nxt())))
    # bundled messages (follow on flag)
    m1 = msg(1, recovery_ts(), fo=True, seq=nxt())
    m2 = msg(1, recovery_ts(), seq=nxt())
    o.add(udp4(m1 + m2))
    m3 = msg(52, pdr_id(2), seid=0x99, fo=True, seq=nxt())
    o.add(udp4(m3 + m1 + m2))
    # unknown message type, reserved, spare bits set
    o.add(udp4(msg(0, b'', seq=nxt())))
    o.add(udp4(msg(99, b'', seq=nxt())))
    o.add(udp4(msg(1, recovery_ts(), seq=nxt(), spare=3)))
    # unmatched response, request answered twice, request resent
    o.add(udp4(msg(2, recovery_ts(), seq=9999), src=UP4, dst=CP4))
    s = nxt()
    o.add(udp4(msg(1, recovery_ts(), seq=s)))
    o.add(udp4(msg(1, recovery_ts(), seq=s)))
    o.add(udp4(msg(2, recovery_ts(), seq=s), src=UP4, dst=CP4))
    o.add(udp4(msg(2, recovery_ts(), seq=s), src=UP4, dst=CP4))
    # IPv6 session establishment
    s = nxt()
    o.add(udp6(msg(50, node_id6() + fseid6(0xc6, CP6) + create_pdr(1, pdi(src_if(0), fteid_ch())), seid=0, seq=s)))
    o.add(udp6(msg(51, cause(1) + fseid46(0xa6), seid=0xc6, seq=s), src=UP6, dst=CP6))

    # ---- 4. one frame per IE type with all useful variants
    o.mark('IE variants: one frame per IE type')
    for t in sorted(IEVARS):
        body = b''.join(ie(t, fl(f, n, x)) for f, n, x in IEVARS[t])
        if len(body) > 60000:
            body = body[:60000]
        o.add(udp4(msg(52, body, seid=0x1234, seq=nxt())))

    o.mark('vendor IE variants')
    for k in sorted(VIEVARS):
        ent, t = divmod(k, 100000)
        body = b''.join(vie(ent, t, fl(f, n, x)) for f, n, x in VIEVARS[k])
        o.add(udp4(msg(52, body, seid=0x1234, seq=nxt())))

    build_extra(o, IEVARS, VIEVARS)

SEQ = [5000]


def nseq():
    SEQ[0] += 1
    return SEQ[0]


def s16(b):
    if isinstance(b, str):
        b = b.encode()
    return struct.pack('!H', len(b)) + b


def s8(b):
    if isinstance(b, str):
        b = b.encode()
    return bytes([len(b)]) + b


